import { Component, OnInit, SecurityContext } from '@angular/core';
import { FormGroup, FormBuilder, Validators } from '@angular/forms';
import { SafeHtml, DomSanitizer } from '@angular/platform-browser';
import { AngularEditorConfig } from '@kolkov/angular-editor';
import { SharedIonic } from '../../../../../core/common/SharedIonic';
import { IProductFilterModel, ProductFilterModel } from '../../../../../data/model/product/ProductFilterModel';
import { IProductDetailModel } from '../../../../../data/model/product/ProductDetailModel';
import { IAddOrUpdateProductModel, AddOrUpdateProductModel } from '../../../../../data/model/product/AddOrUpdateProductModel';
import { ProductService } from '../../../../../data/service/product/product.service';
import { ToastController, LoadingController, AlertController } from '@ionic/angular';
import { ActivatedRoute, Router } from '@angular/router';
import { G } from '../../../../../core/common/G';
import { GResponse } from '../../../../../core/common/GResponse';
import { IProductModel } from '../../../../../data/model/product/ProductModel';

@Component({
  selector: 'app-update-product',
  templateUrl: './update-product.component.html',
  styleUrls: ['./update-product.component.scss']
})
export class UpdateProductComponent implements OnInit {

  isCan = true;
  priceType = 'price';
  sellerPercent = 0;
  sellerPrice = 0;
  searchTitle = '';

  isGuaranteeShow = false;
  hasDiscountLargeOrder = false;
  discountByPercent = false;
  referable = false;
  referableByPercent = false;
  hasExtraDeliveryPrice = false;

  editorConfig: AngularEditorConfig = {
    editable: true,
    spellcheck: true,
    height: '25rem',
    minHeight: '5rem',
    placeholder: 'توضیحات کوتاه...',
    translate: 'no',
    sanitize: true
  };

  editorConfig2: AngularEditorConfig = {
    editable: true,
    spellcheck: true,
    height: '25rem',
    minHeight: '5rem',
    placeholder: 'توضیحات اصلی...',
    translate: 'no',
    sanitize: true
  };

  selectedProductId = 0;
  productSelected = false;
  productDetail: IProductDetailModel;
  filteredProducts: IProductFilterModel;
  shortDescription: SafeHtml;
  description: SafeHtml;
  updateProductForm: FormGroup;
  productCategoryIds: number[] = [];
  mechanicCategories = [];
  tuningCategories = [];
  designeCategories = [];
  empty = false;

  product: IAddOrUpdateProductModel;

  constructor(
    private productService: ProductService,
    private fb: FormBuilder,
    public toastController: ToastController,
    public loadingController: LoadingController,
    private activatedRoute: ActivatedRoute,
    private router: Router,
    private domSanitizer: DomSanitizer,
    public alertController: AlertController) { }

  ngOnInit(): void {

    this.updateProductForm = this.fb.group({
      name: ['', [Validators.required, Validators.minLength(3), Validators.maxLength(200)]],
      referableReducePrice: [0, [Validators.min(0), Validators.max(200000000)]],
      referableReducePercent: [0, [Validators.min(0), Validators.max(10000)]],
      sendTime: [3, [Validators.required, Validators.min(0), Validators.max(180)]],
      count: [0, [Validators.required, Validators.min(0), Validators.max(20000000)]],
      discountOrderCount: [0, [Validators.min(0), Validators.max(20000000)]],
      discountPrice: [0, [Validators.min(0), Validators.max(90000000000)]],
      maxDiscountPrice: [0, [Validators.min(0), Validators.max(90000000000)]],
      discountPercent: [0, [Validators.min(0), Validators.max(10000)]],
      maxDiscountPercent: [0, [Validators.min(0), Validators.max(10000)]],
      weight: [1000, [Validators.required, Validators.min(1), Validators.max(20000000)]],
      price: [0, [Validators.required, Validators.min(1000), Validators.max(90000000000)]],
      offPrice: [0, [Validators.required, Validators.min(0), Validators.max(90000000000)]],
      imageName: ['http://localhost:4300/assets/images/in-progress.webp', [Validators.minLength(1), Validators.maxLength(1000000)]],
      imageNamePNG: ['http://localhost:4300/assets/images/in-progress.png', [Validators.minLength(1), Validators.maxLength(1000000)]],
      guaranteeDescription: ['', [Validators.minLength(0), Validators.maxLength(1000000)]],
      referableDescription: ['', [Validators.minLength(0), Validators.maxLength(1000000)]],
      shortDescription: ['', [Validators.required, Validators.minLength(10), Validators.maxLength(1000000)]],
      description: ['', [Validators.required, Validators.minLength(10), Validators.maxLength(1000000)]],
      isPostSend: [true, [Validators.required]],
      isSpecialPostSend: [true, [Validators.required]],
      isOwnDeliverySend: [true, [Validators.required]],
      isTipaxSend: [true, [Validators.required]],
      isTipaxSoRentSend: [true, [Validators.required]],
      isBurberrySend: [true, [Validators.required]],
      isBikeDeliverySend: [true, [Validators.required]],
      isExists: [true, [Validators.required]],
      isShow: [true, [Validators.required]],
      extraDeliveryPrice: [0, [Validators.required, Validators.min(0), Validators.max(90000000000)]],
      hasExtraDeliveryPrice: [false, [Validators.required]],
      isCorrupt: [false, [Validators.required]],
      referable: [false, [Validators.required]],
      consumption: [false, [Validators.required]],
      hasSeveralDesigns: [false, [Validators.required]],
      hasGuarantee: [false, [Validators.required]],
      hasPrivateDownloadLinks: [false, [Validators.required]],
      hasDiscountLargeOrder: [false, [Validators.required]],
      hasDiscountForEachOrder: [false, [Validators.required]],
      isUsed: [false, [Validators.required]],
      isFreeSend: [false, [Validators.required]],
      isWholesale: [false, [Validators.required]]
    });

    this.mechanicCategories = [];
    this.tuningCategories = [];
    this.designeCategories = [];

    G.getProductCategory().subscribe(
      res => {

        if (res != null) {
          if (res.length > 0) {
            res.forEach(c => {

              if (c.parentId == 1) {
                this.mechanicCategories.push(c);
              } else if (c.parentId == 2) {
                this.tuningCategories.push(c);
              } else if (c.parentId == 3) {
                this.designeCategories.push(c);
              }
            });
          }
        }
      }
    );

    let filter: IProductFilterModel;

    this.activatedRoute.queryParams.subscribe(params => {

      const page = params.page ? params.page : 1;
      const take = params.take ? params.take : 12;
      const title = params.title ? params.title : null;
      const startPrice = params.startPrice ? params.startPrice : null;
      const endPrice = params.endPrice ? params.endPrice : null;
      const categoryIds = params.categoryIds ? params.categoryIds : null;
      const sortId = params.sortId ? params.sortId : 4;

      if (page === undefined) {
        filter = new ProductFilterModel(false, page, take, title);
      } else {
        if (
          startPrice == null &&
          endPrice == null &&
          categoryIds == null &&
          sortId == null) {

          filter = new ProductFilterModel(false, page, take, title);
        } else {
          filter =
          new ProductFilterModel(true, page, take, title, startPrice, endPrice, false, false, categoryIds, sortId, false);
        }
      }
      this.filteredProducts = filter;

      SharedIonic.loading(this.loadingController);

      this.productService.GetSellerProductsByFilter(filter).subscribe(
        res => {
          SharedIonic.dismissLoading(this.loadingController);
          if (res.status === GResponse.SuccessStatus) {
            this.filteredProducts = res.data;
          } else {
            // SharedIonic.unSuccessToast(this.toastController);
            this.empty = true;
          }
        },
        err => {
          SharedIonic.dismissLoading(this.loadingController);
          SharedIonic.unSuccessToast(this.toastController);
        }
      );
    });
  }

  onPriceTypeChanged() {

    if (!this.isCan) {

      return;
    }

    if (this.priceType === 'price') {
      this.updateProductForm.setValue({
        name: this.updateProductForm.value.name,
        price: this.updateProductForm.value.price,
        offPrice: 0,
        imageName: this.updateProductForm.value.imageName,
        imageNamePNG: this.updateProductForm.value.imageNamePNG,
        shortDescription: this.updateProductForm.value.shortDescription,
        description: this.updateProductForm.value.description,
        referableReducePrice: this.updateProductForm.value.referableReducePrice,
        referableReducePercent: this.updateProductForm.value.referableReducePercent,
        sendTime: this.updateProductForm.value.sendTime,
        count: this.updateProductForm.value.count,
        discountOrderCount: this.updateProductForm.value.discountOrderCount,
        discountPrice: this.updateProductForm.value.discountPrice,
        maxDiscountPrice: this.updateProductForm.value.maxDiscountPrice,
        discountPercent: this.updateProductForm.value.discountPercent,
        maxDiscountPercent: this.updateProductForm.value.maxDiscountPercent,
        weight: this.updateProductForm.value.weight,
        guaranteeDescription: this.updateProductForm.value.guaranteeDescription,
        referableDescription: this.updateProductForm.value.referableDescription,
        isPostSend: this.updateProductForm.value.isPostSend,
        isTipaxSend: this.updateProductForm.value.isTipaxSend,
        isTipaxSoRentSend: this.updateProductForm.value.isTipaxSoRentSend,
        isBurberrySend: this.updateProductForm.value.isBurberrySend,
        isBikeDeliverySend: this.updateProductForm.value.isBikeDeliverySend,
        isSpecialPostSend: this.updateProductForm.value.isSpecialPostSend,
        isOwnDeliverySend: this.updateProductForm.value.isOwnDeliverySend,
        isExists: this.updateProductForm.value.isExists,
        isShow: this.updateProductForm.value.isShow,
        isCorrupt: this.updateProductForm.value.isCorrupt,
        referable: this.updateProductForm.value.referable,
        consumption: this.updateProductForm.value.consumption,
        hasSeveralDesigns: this.updateProductForm.value.hasSeveralDesigns,
        hasGuarantee: this.updateProductForm.value.hasGuarantee,
        hasPrivateDownloadLinks: this.updateProductForm.value.hasPrivateDownloadLinks,
        hasDiscountLargeOrder: this.updateProductForm.value.hasDiscountLargeOrder,
        hasDiscountForEachOrder: this.updateProductForm.value.hasDiscountForEachOrder,
        isUsed: this.updateProductForm.value.isUsed,
        isFreeSend: this.updateProductForm.value.isFreeSend,
        isWholesale: this.updateProductForm.value.isWholesale,
        extraDeliveryPrice: this.updateProductForm.value.extraDeliveryPrice,
        hasExtraDeliveryPrice: this.updateProductForm.value.hasExtraDeliveryPrice
      });
    } else if (this.priceType === 'offPrice') {
      this.updateProductForm.setValue({
        name: this.updateProductForm.value.name,
        price: this.updateProductForm.value.price,
        offPrice: '',
        imageName: this.updateProductForm.value.imageName,
        imageNamePNG: this.updateProductForm.value.imageNamePNG,
        shortDescription: this.updateProductForm.value.shortDescription,
        description: this.updateProductForm.value.description,
        referableReducePrice: this.updateProductForm.value.referableReducePrice,
        referableReducePercent: this.updateProductForm.value.referableReducePercent,
        sendTime: this.updateProductForm.value.sendTime,
        count: this.updateProductForm.value.count,
        discountOrderCount: this.updateProductForm.value.discountOrderCount,
        discountPrice: this.updateProductForm.value.discountPrice,
        maxDiscountPrice: this.updateProductForm.value.maxDiscountPrice,
        discountPercent: this.updateProductForm.value.discountPercent,
        maxDiscountPercent: this.updateProductForm.value.maxDiscountPercent,
        weight: this.updateProductForm.value.weight,
        guaranteeDescription: this.updateProductForm.value.guaranteeDescription,
        referableDescription: this.updateProductForm.value.referableDescription,
        isPostSend: this.updateProductForm.value.isPostSend,
        isTipaxSend: this.updateProductForm.value.isTipaxSend,
        isTipaxSoRentSend: this.updateProductForm.value.isTipaxSoRentSend,
        isBurberrySend: this.updateProductForm.value.isBurberrySend,
        isBikeDeliverySend: this.updateProductForm.value.isBikeDeliverySend,
        isSpecialPostSend: this.updateProductForm.value.isSpecialPostSend,
        isOwnDeliverySend: this.updateProductForm.value.isOwnDeliverySend,
        isExists: this.updateProductForm.value.isExists,
        isShow: this.updateProductForm.value.isShow,
        isCorrupt: this.updateProductForm.value.isCorrupt,
        referable: this.updateProductForm.value.referable,
        consumption: this.updateProductForm.value.consumption,
        hasSeveralDesigns: this.updateProductForm.value.hasSeveralDesigns,
        hasGuarantee: this.updateProductForm.value.hasGuarantee,
        hasPrivateDownloadLinks: this.updateProductForm.value.hasPrivateDownloadLinks,
        hasDiscountLargeOrder: this.updateProductForm.value.hasDiscountLargeOrder,
        hasDiscountForEachOrder: this.updateProductForm.value.hasDiscountForEachOrder,
        isUsed: this.updateProductForm.value.isUsed,
        isFreeSend: this.updateProductForm.value.isFreeSend,
        isWholesale: this.updateProductForm.value.isWholesale,
        extraDeliveryPrice: this.updateProductForm.value.extraDeliveryPrice,
        hasExtraDeliveryPrice: this.updateProductForm.value.hasExtraDeliveryPrice
      });
    }
  }

  async presentAlertConfirm() {
    const alert = await this.alertController.create({
      cssClass: 'main-alert',
      header: 'هشدار!',
      message: 'آیا مطمئن هستید؟',
      buttons: [
        {
          text: 'لغو',
          role: 'cancel',
          cssClass: 'secondary',
          handler: () => {
          }
        }, {
          text: 'بله',
          handler: () => {
            this.onUpdate();
          }
        }
      ]
    });

    await alert.present();
  }

  onCategoryChecked(categoryId: number | string) {

    if (this.productCategoryIds.find(c => c == categoryId) == null) {

      this.productCategoryIds.push(+categoryId);
    } else {
      this.productCategoryIds.splice(this.productCategoryIds.findIndex(c => c == categoryId), 1);
    }
  }

  checkCategoryId(categoryId: number | string): boolean {

    if (this.productCategoryIds.find(c => c == categoryId) == null) {

      return false;
    } else {

      return true;
    }
  }

  onUpdate() {

    if (this.updateProductForm.valid) {

      if (this.productCategoryIds.length < 1) {

        SharedIonic.toast(this.toastController, 'گروهی انتخاب نشده است');
        return;
      }

      if (+this.updateProductForm.value.offPrice > +this.updateProductForm.value.price) {

        SharedIonic.toast(this.toastController, 'تخفیف بیشتر از قیمت اصلی است');
        return;
      }

      SharedIonic.loading(this.loadingController);

      // this.shortDescription = this.domSanitizer
      //   .sanitize(SecurityContext.HTML, this.updateCourseForm.value.shortDescriptionHtmlContent);

      this.shortDescription = this.updateProductForm.value.shortDescriptionHtmlContent;

      this.description = this.domSanitizer
        .sanitize(SecurityContext.HTML, this.updateProductForm.value.descriptionHtmlContent);

      this.product =
        new AddOrUpdateProductModel(
          this.selectedProductId,
          this.updateProductForm.value.name,
          !this.referable ? 0 : (this.referableByPercent ? 0 : this.updateProductForm.value.referableReducePrice),
          !this.referable ? 0 : (!this.referableByPercent ? 0 : this.updateProductForm.value.referableReducePercent),
          this.updateProductForm.value.sendTime,
          this.updateProductForm.value.count,
          this.updateProductForm.value.price,
          this.updateProductForm.value.offPrice,
          this.updateProductForm.value.guaranteeDescription,
          this.updateProductForm.value.referableDescription,
          this.updateProductForm.value.shortDescription,
          this.updateProductForm.value.description,
          this.updateProductForm.value.imageName,
          this.updateProductForm.value.imageNamePNG,
          this.updateProductForm.value.isPostSend,
          this.updateProductForm.value.isTipaxSend,
          this.updateProductForm.value.isTipaxSoRentSend,
          this.updateProductForm.value.isBurberrySend,
          this.updateProductForm.value.isBikeDeliverySend,
          this.updateProductForm.value.isExists,
          this.updateProductForm.value.isShow,
          this.updateProductForm.value.isCorrupt,
          false,
          false,
          this.updateProductForm.value.referable,
          this.updateProductForm.value.consumption,
          this.updateProductForm.value.hasSeveralDesigns,
          this.updateProductForm.value.hasGuarantee,
          this.updateProductForm.value.hasPrivateDownloadLinks,
          this.updateProductForm.value.hasDiscountLargeOrder,
          !this.hasDiscountLargeOrder ? false : this.updateProductForm.value.hasDiscountForEachOrder,
          this.discountByPercent || !this.hasDiscountLargeOrder ? 0 : this.updateProductForm.value.discountPrice,
          this.discountByPercent || !this.hasDiscountLargeOrder ? 0 : this.updateProductForm.value.maxDiscountPrice,
          !this.discountByPercent || !this.hasDiscountLargeOrder ? 0 : this.updateProductForm.value.discountPercent,
          !this.discountByPercent || !this.hasDiscountLargeOrder ? 0 : this.updateProductForm.value.maxDiscountPercent,
          !this.hasDiscountLargeOrder ? 0 : this.updateProductForm.value.discountOrderCount,
          this.priceType == 'offPrice',
          100,
          this.updateProductForm.value.weight,
          false,
          false,
          this.updateProductForm.value.isUsed,
          this.updateProductForm.value.isFreeSend,
          this.updateProductForm.value.isWholesale,
          this.productCategoryIds,
          this.updateProductForm.value.isOwnDeliverySend,
          this.updateProductForm.value.isSpecialPostSend,
          this.updateProductForm.value.hasExtraDeliveryPrice,
          this.hasExtraDeliveryPrice ? this.updateProductForm.value.extraDeliveryPrice : 0
        );

      this.productService.AddOrUpdateProduct(this.product).subscribe(
        res => {

          if (GResponse.SuccessStatus === res.status) {

            this.filteredProducts = new ProductFilterModel(false);

            this.productService.GetSellerProductsByFilter(this.filteredProducts).subscribe(
              res => {
                SharedIonic.dismissLoading(this.loadingController);
                if (res.status === GResponse.SuccessStatus) {
                  this.productSelected = false;
                  this.filteredProducts = res.data;
                  SharedIonic.successToast(this.toastController);
                } else {
                  SharedIonic.unSuccessToast(this.toastController);
                }
              },
              err => {
                SharedIonic.dismissLoading(this.loadingController);
                SharedIonic.unSuccessToast(this.toastController);
              }
            );
          } else {
            SharedIonic.dismissLoading(this.loadingController);
            SharedIonic.unSuccessToast(this.toastController);
          }
        },
        err => {
          SharedIonic.dismissLoading(this.loadingController);
          SharedIonic.unSuccessToast(this.toastController);
        }
      );
    }
  }

  MakePageCountArray(pageCount: number | string): Array<number | string> {

    const array: string[] = [];

    for (let i = 1; i <= pageCount; i++) {

      array.push(i.toString());
    }

    return array;
  }

  goPreviousPage() {

    if (this.filteredProducts.startPage == null) {
      return;
    }
    if (this.filteredProducts.pageId > this.filteredProducts.startPage && +this.filteredProducts.pageId - 1 > 0) {
      this.setQueryParams(+this.filteredProducts.pageId - 1);
    }
  }

  goNextPage() {

    if (this.filteredProducts.endPage == null) {
      return;
    }
    if (this.filteredProducts.pageId < this.filteredProducts.endPage) {
      this.setQueryParams(+this.filteredProducts.pageId + 1);
    }
  }

  goPage(pageId: number | string) {
    this.setQueryParams(+pageId);
  }

  setQueryParams(pageId: number) {

    this.filteredProducts.title = this.searchTitle;

    this.router
      .navigate(
        ['SellerPanel', 'UpdateProduct'],
        {
          queryParams:
          {
            page: pageId < 1 ? 1 : pageId,
            take: this.filteredProducts.takeEntity ? this.filteredProducts.takeEntity : null,
            title: this.filteredProducts.title ? this.filteredProducts.title : null,
            startPrice: this.filteredProducts.startPrice ? this.filteredProducts.startPrice : null,
            endPrice: this.filteredProducts.endPrice ? this.filteredProducts.endPrice : null,
            categoryIds: this.filteredProducts.categoryIds ? this.filteredProducts.categoryIds : [],
            sortId: this.filteredProducts.sortId ? this.filteredProducts.sortId : 0
          }
        });
  }

  onGuaranteeClicked(checked) {

    this.isGuaranteeShow = checked.detail.checked;
  }

  onhasDiscountLargeOrderClicked(checked) {

    this.hasDiscountLargeOrder = checked.detail.checked;
  }

  onDiscountByPercentClicked(checked) {

    this.discountByPercent = checked.detail.checked;
  }

  onReferableClicked(checked) {

    this.referable = checked.detail.checked;
  }

  onReferableByPercentClicked(checked) {

    this.referableByPercent = checked.detail.checked;
  }

  onExtraDeliveryPriceClicked(checked) {

    this.hasExtraDeliveryPrice = checked.detail.checked;
  }

  onSelectItem(model: IProductModel) {

    SharedIonic.loading(this.loadingController);

    this.selectedProductId = +model.id;

    this.productService.GetProductEditById(+model.id).subscribe(

      res => {
        SharedIonic.dismissLoading(this.loadingController);
        if (GResponse.SuccessStatus === res.status) {
          this.isCan = false;
          this.productDetail = res.data;
          this.productCategoryIds = res.data.categoryIds;
          this.sellerPrice = res.data.portionPrice;
          this.sellerPercent = res.data.portionPercent;

          this.updateProductForm.setValue({
            name: res.data.name,
            price: res.data.price,
            offPrice: res.data.offPrice,
            imageName: res.data.imageName,
            imageNamePNG: res.data.imageNamePNG,
            shortDescription: res.data.shortDescription,
            description: res.data.description,
            referableReducePrice: res.data.referableReducePrice,
            referableReducePercent: res.data.referableReducePercent,
            sendTime: res.data.sendTime,
            count: res.data.count,
            discountOrderCount: res.data.discountOrderCount,
            discountPrice: res.data.discountPrice,
            maxDiscountPrice: res.data.maxDiscountPrice,
            discountPercent: res.data.discountPercent,
            maxDiscountPercent: res.data.maxDiscountPercent,
            weight: res.data.weight,
            guaranteeDescription: res.data.guaranteeDescription,
            referableDescription: res.data.referableDescription,
            isPostSend: res.data.isPostSend,
            isTipaxSend: res.data.isTipaxSend,
            isTipaxSoRentSend: res.data.isTipaxSoRentSend,
            isBurberrySend: res.data.isBurberrySend,
            isBikeDeliverySend: res.data.isBikeDeliverySend,
            isSpecialPostSend: res.data.isSpecialPostSend,
            isOwnDeliverySend: res.data.isOwnDeliverySend,
            isExists: res.data.isExists,
            isShow: res.data.isShow,
            isCorrupt: res.data.isCorrupt,
            referable: res.data.referable,
            hasExtraDeliveryPrice: res.data.hasExtraDeliveryPrice,
            extraDeliveryPrice: res.data.extraDeliveryPrice,
            consumption: res.data.consumption,
            hasSeveralDesigns: res.data.hasSeveralDesigns,
            hasGuarantee: res.data.hasGuarantee,
            hasPrivateDownloadLinks: res.data.hasPrivateDownloadLinks,
            hasDiscountLargeOrder: res.data.hasDiscountLargeOrder,
            hasDiscountForEachOrder: res.data.hasDiscountForEachOrder,
            isUsed: res.data.isUsed,
            isFreeSend: res.data.isFreeSend,
            isWholesale: res.data.isWholesale
          });

          this.isGuaranteeShow = res.data.hasGuarantee;
          this.referable = res.data.referable;
          this.referableByPercent = res.data.referableReducePrice == 0;
          this.hasExtraDeliveryPrice = res.data.hasExtraDeliveryPrice;
          this.hasDiscountLargeOrder = res.data.hasDiscountLargeOrder;
          this.discountByPercent = res.data.discountPrice == 0;

          if (this.productDetail.offPrice != 0 && this.productDetail.price != 0) {
            this.priceType = 'offPrice';
          } else if (this.productDetail.offPrice == 0 && this.productDetail.price != 0) {
            this.priceType = 'price';
          } else {
            this.priceType = 'price';
          }
          this.productSelected = true;
          this.isCan = true;

        } else {
          SharedIonic.unSuccessToast(this.toastController);
          this.selectedProductId = 0;
          this.productSelected = false;
        }
      },
      err => {
        SharedIonic.dismissLoading(this.loadingController);
        SharedIonic.toast(this.toastController, 'خطایی رخ داده است');
        this.selectedProductId = 0;
        this.productSelected = false;
      }
    );
  }

  onCancel() {

    this.selectedProductId = 0;
    this.productSelected = false;
  }
}
